<script setup lang="ts">
import { ref, onMounted } from 'vue'
import { useAuth } from '../stores/auth'
import { get, post, put, del } from '../api'
import { ElMessage, ElMessageBox } from 'element-plus'
import StatusTag from '../components/StatusTag.vue'
const auth=useAuth(),items=ref<any[]>([]),dialog=ref(false),editing=ref<any>(null),form=ref<any>({}),resetOpen=ref(false),resetUser=ref<any>(null),newPassword=ref('')
async function load(){items.value=(await get('/users')).items||[]}
function randomPassword(){const letters='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz',digits='23456789',chars=letters+digits,b=crypto.getRandomValues(new Uint8Array(16)),out=[letters[b[0]%letters.length],digits[b[1]%digits.length],...Array.from(b.slice(2),x=>chars[x%chars.length])];for(let i=out.length-1;i>0;i--){const j=b[i%b.length]%(i+1);[out[i],out[j]]=[out[j],out[i]]}return out.join('')}
function add(){editing.value=null;form.value={username:'',password:randomPassword(),role:'viewer',enabled:true};dialog.value=true}
function edit(u:any){editing.value=u;form.value={...u};dialog.value=true}
async function save(){if(editing.value)await put(`/users/${editing.value.id}`,form.value);else await post('/users',form.value);ElMessage.success('已保存');dialog.value=false;load()}
async function remove(u:any){await ElMessageBox.confirm(`删除用户「${u.username}」？`,'确认删除',{type:'warning'});await del(`/users/${u.id}`);load()}
function reset(u:any){resetUser.value=u;newPassword.value=randomPassword();resetOpen.value=true}
async function submitReset(){await post(`/users/${resetUser.value.id}/reset-password`,{password:newPassword.value});ElMessage.success('密码已重置');resetOpen.value=false}
onMounted(load)
</script><template><div class="page"><div class="page-head"><div><h1>用户管理</h1><p>管理平台成员与访问权限</p></div><el-button type="primary" @click="add">+ 新增用户</el-button></div><div class="stats"><div class="card stat"><strong>{{items.length}}</strong><span>用户总数</span></div><div class="card stat"><strong>{{items.filter(x=>x.role==='admin').length}}</strong><span>管理员</span></div><div class="card stat"><strong>{{items.filter(x=>x.role==='viewer').length}}</strong><span>只读用户</span></div></div><div class="roles grid-2"><div class="card panel"><h3>管理员 admin</h3><p>纳管账号、触发同步、管理用户并查看审计日志</p></div><div class="card panel"><h3>只读用户 viewer</h3><p>查看概览、资源和监控，不能修改配置</p></div></div><div class="card table-card"><el-table :data="items"><el-table-column label="用户" min-width="170"><template #default="{row}"><div class="person"><span class="avatar">{{row.username[0].toUpperCase()}}</span><strong>{{row.username}}</strong><el-tag v-if="row.id===auth.user?.id" size="small" type="info">当前登录</el-tag></div></template></el-table-column><el-table-column label="角色"><template #default="{row}">{{row.role==='admin'?'管理员':'只读用户'}}</template></el-table-column><el-table-column label="状态"><template #default="{row}"><StatusTag :status="row.enabled?'running':'stopped'"/><span v-if="row.today_failed_logins" class="failed">今天 {{row.today_failed_logins}} 次登录失败</span></template></el-table-column><el-table-column label="最近登录"><template #default="{row}">{{row.last_login_at?new Date(row.last_login_at).toLocaleString('zh-CN'):'从未登录'}}</template></el-table-column><el-table-column prop="last_login_ip" label="登录 IP"/><el-table-column label="操作" width="220"><template #default="{row}"><template v-if="row.id!==auth.user?.id"><el-button text type="primary" @click="edit(row)">编辑</el-button><el-button text @click="reset(row)">重置密码</el-button><el-button text type="danger" @click="remove(row)">删除</el-button></template></template></el-table-column></el-table></div><el-dialog v-model="dialog" :title="editing?'编辑用户':'新增用户'" width="430px"><el-form label-position="top"><el-form-item label="用户名"><el-input v-model="form.username" :disabled="!!editing"/></el-form-item><el-form-item v-if="!editing" label="初始密码（至少 10 位，含字母和数字）"><el-input v-model="form.password"><template #append><el-button @click="form.password=randomPassword()">随机生成</el-button></template></el-input></el-form-item><el-form-item label="角色"><el-select v-model="form.role"><el-option label="管理员" value="admin"/><el-option label="只读用户" value="viewer"/></el-select></el-form-item><el-form-item v-if="editing" label="启用"><el-switch v-model="form.enabled"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog><el-dialog v-model="resetOpen" title="重置密码" width="430px"><p>为 {{resetUser?.username}} 设置新密码（至少 10 位，含字母和数字）：</p><el-input v-model="newPassword"/><template #footer><el-button @click="resetOpen=false">取消</el-button><el-button type="primary" @click="submitReset">确认重置</el-button></template></el-dialog></div></template>
<style scoped>.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.stat{padding:20px;display:flex;gap:14px;align-items:baseline}.stat strong{font-size:26px}.stat span{color:var(--subtle)}.roles{margin:14px 0}.roles h3{font-size:14px;margin:0 0 8px}.roles p{color:var(--subtle);font-size:12px;margin:0}.table-card{padding:8px 16px}.person{display:flex;align-items:center;gap:9px}.avatar{background:#E5EBFF;color:var(--primary);width:30px;height:30px;display:grid;place-items:center;border-radius:50%}.failed{display:block;color:var(--amber);font-size:11px;margin-top:5px}</style>
